[
  {
    "taxonId": 58228,
    "summary": "Flowering-plant genus native across temperate Northern Hemisphere regions of Eurasia, North Africa and western North America. Most peonies are herbaceous perennials, though some are shrubs; they are popular garden plants, and herbaceous kinds are widely sold as late-spring and early-summer cut flowers.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 58300,
    "summary": "Fruit-bearing deciduous shrub native to the Caucasus and Iranian plateau, including modern Iran, Turkmenistan, Afghanistan and Pakistan. Its spiny branches bear bright red or white flowers and thick reddish fruits divided into seed-filled chambers. The fleshy seed coats and pulp are edible; the fruit and juice are used in drinks, baking, cooking and garnishes.",
    "humanEdibility": "yes",
    "edibilityNote": "The seeds and pulp are edible; the fruit and juice are used in drinks, cooking, baking and garnishes.",
    "evidence": {
      "summary": ["s1:p2", "s1:p5", "s1:p12", "s1:p13", "s1:p14"],
      "humanEdibility": ["s1:p5", "s1:p14"]
    }
  },
  {
    "taxonId": 58333,
    "summary": "Flowering-shrub genus distributed across temperate and subtropical regions on most continents, especially South America, North America and southern Africa. Plants are often thorny, with small fleshy leaves, white, green or purple bell-shaped flowers, and berries that may be red, orange, yellow or black.",
    "humanEdibility": "unknown",
    "edibilityNote": "Fruits of L. barbarum and L. chinense are eaten dried, but this does not establish edibility for the whole genus.",
    "evidence": {
      "summary": ["s1:p2", "s1:p6"],
      "humanEdibility": ["s1:p10"]
    }
  },
  {
    "taxonId": 58335,
    "summary": "Herb and shrub genus indigenous to the Americas, Australia, southwestern Africa and the South Pacific. Species vary in nicotine and related defensive chemicals, which deter most herbivores, while several species are cultivated as tobacco plants.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p11"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 58363,
    "summary": "Small flowering-plant genus native to Mexico and the southwestern United States. Its thick flower stalk bears downward-bent bracts, and its sticky pollen is released as a mass rather than as separate grains.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p1", "s1:p2"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 58365,
    "summary": "Annual or perennial grass genus widespread across temperate and subtropical Eurasia, northern Africa and the Americas, and naturalized in Australia and various islands. Plants grow in tufts with flat leaves and dense flower heads; some are weeds, while others are valued in dried-flower bouquets.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 58374,
    "summary": "Widespread grass genus found across Europe, Africa, Asia, Australasia, the Pacific and the Americas. Some species are cereal or fodder millets, while others become troublesome farm weeds; early barnyard grass can resemble rice closely enough to escape weeding.",
    "humanEdibility": "yes",
    "edibilityNote": "Some species are cereal crops, including Japanese, Indian barnyard, burgu and channel millets; this does not apply to every species.",
    "evidence": {
      "summary": ["s1:p1", "s1:p2", "s1:p3", "s2:p3"],
      "humanEdibility": ["s1:p2"]
    }
  },
  {
    "taxonId": 58379,
    "summary": "Annual grass native to the Mediterranean Basin and neighbouring regions, from Portugal and the Canary Islands east to Ethiopia and northern India. It has conspicuous clusters of golden flowers and favours dry, stony places in Portugal; it is naturalized in parts of Australia and the Americas, sometimes as an invasive weed.",
    "humanEdibility": "unknown",
    "edibilityNote": null,
    "evidence": {
      "summary": ["s1:p2", "s1:p3", "s3:p1", "s3:p2"],
      "humanEdibility": []
    }
  },
  {
    "taxonId": 58388,
    "summary": "Grass genus closely related to maize and millets. Some wild Sorghum species are perennial.",
    "humanEdibility": "unknown",
    "edibilityNote": "Food use is stated for Australian S. intrans and S. plumosum, not for the genus as a whole.",
    "evidence": {
      "summary": ["s1:p6", "s1:p10"],
      "humanEdibility": ["s1:p54"]
    }
  },
  {
    "taxonId": 58389,
    "summary": "Usually annual, clump-forming grass native to Africa and the Indian subcontinent, with its origin and first domestication in Sudan. Its large bushy flower heads produce edible starchy grain. Young milky grain can be eaten raw, while mature grain must be boiled or ground into flour.",
    "humanEdibility": "yes",
    "edibilityNote": "Young milky grain may be eaten raw; mature grain must be boiled or ground into flour.",
    "evidence": {
      "summary": ["s1:p2", "s1:p3", "s1:p6", "s1:p15", "s1:p38"],
      "humanEdibility": ["s1:p38"]
    }
  }
]
